onCreate: function () {
  const context = this.getView().getModel().createEntry("/Products", {
    properties: { Name: "", Price: "0.00" }
  });
  this.getView().setBindingContext(context); // the form edits the new entry
},

onSave: function () {
  this.getView().getModel().submitChanges({
    success: function () { /* sent in one $batch */ }
  });
},

onCancel: function () {
  this.getView().getModel().resetChanges();
}

onApprove: function () {
  const orderId = this.getView().getBindingContext().getProperty("OrderID");
  this.getView().getModel().callFunction("/ApproveOrder", {
    method: "POST",
    urlParameters: { OrderID: orderId },
    success: function (result) {
      MessageToast.show("Order approved");
    },
    error: function () {
      MessageBox.error("Approval failed");
    }
  });
}

